package vn.codegym.salesinventory.controller;
import jakarta.servlet.http.*;import vn.codegym.salesinventory.service.*;import vn.codegym.salesinventory.validation.CatalogValidation;
public final class UnitServlet extends PortalServlet {
 protected void get(HttpServletRequest r,HttpServletResponse s)throws Exception{r.setAttribute("products",new ProductService(source()).list(actor(r).id(),value(r,"q"),null,"",1));long product=value(r,"product").isEmpty()?0:number(r,"product");r.setAttribute("productId",product);if(product!=0)r.setAttribute("units",new UnitService(source()).list(actor(r).id(),product));if(value(r,"action").equals("convert")){var v=new UnitService(source()).convert(actor(r).id(),number(r,"id"),CatalogValidation.decimal(value(r,"quantity"),6,false));r.setAttribute("conversion",v.quantity()+" "+v.unitName()+" = "+v.baseQuantity()+" đơn vị cơ sở (hệ số "+v.factor()+", phiên bản "+v.version()+")");}r.setAttribute("warehouses",access(r).warehouses());view(r,s,"catalog/units");}
 protected void post(HttpServletRequest r,HttpServletResponse s)throws Exception{var service=new UnitService(source());long product=number(r,"product");long id=value(r,"id").isEmpty()?0:number(r,"id");if(value(r,"action").equals("delete"))service.delete(actor(r).id(),id);else service.save(actor(r).id(),id,product,value(r,"name"),CatalogValidation.decimal(value(r,"factor"),6,true),number(r,"warehouse"),value(r,"version").isEmpty()?0:number(r,"version"));redirect(r,s,"/catalog/units?product="+product);}
}
